SELECT traficsourceid, searchengineid, advengineid, CASE WHEN ((searchengineid = 0) AND (advengineid = 0)) THEN referer ELSE '' END, url, count(*) FROM (SELECT * FROM streamed_table('/pgch_3043907_1_1_0', 'eventdate Date, counterid Int32, url String, referer String, isrefresh Int16, traficsourceid Int16, searchengineid Int16, advengineid Int16')) WHERE ((eventdate >= '2013-07-01')) AND ((eventdate <= '2013-07-31')) AND ((counterid = 62)) AND ((isrefresh = 0)) GROUP BY traficsourceid, searchengineid, advengineid, (CASE WHEN ((searchengineid = 0) AND (advengineid = 0)) THEN referer ELSE '' END), url ORDER BY count(*) DESC NULLS FIRST, traficsourceid ASC NULLS LAST, searchengineid ASC NULLS LAST, advengineid ASC NULLS LAST, CASE WHEN ((searchengineid = 0) AND (advengineid = 0)) THEN referer ELSE '' END ASC NULLS LAST, url ASC NULLS LAST LIMIT 10 OFFSET 1000
